-- 017_n1_words_ise
-- N1 單字匯入：ise（共 1714 字）
-- 資料源：stephenmk/yomitan-jlpt-vocab (CC-BY, Jonathan Waller / Tanos)
-- 中文翻譯：Claude（學生友善口語風格）

with new_words as (
  returning id, lemma
)
select
  (select id from shrines where slug = 'ise'),
  nw.id,
  row_number() over (order by nw.lemma)
from new_words nw;
